export const MODULE_TEXT: Record<string, string> = {"74nqgb9lu10c": "<div class=\"gff-choose-prompt\">\n<div class=\"gff-choose-prompt\">\n<p style=\"text-align: center; color: #5a6b52; font-style: italic;\"><span style=\"color: #333333;\">[gff_zora_display]</span></p>\n\n</div>\n</div>\n[gff_form_end]", "3olaigmsw7pb": "[gff_consult]\n\n[gff_express_email]\n<div id=\"reserve'\">[gff_express_submit]</div>\n<div></div>\n<p class=\"font-claude-response-body break-words whitespace-normal\">How it works: we design, plant, and care for a real food garden at your home — as hands-on or hands-off as you like. Two ways we can grow it:</p>\n<p class=\"font-claude-response-body break-words whitespace-normal\"><strong>Sunrise Garden</strong> — An in-ground food forest, best if you have yard or ground to plant.</p>\n<p class=\"font-claude-response-body break-words whitespace-normal\"><strong>Spire Towers</strong> — Vertical growing towers, perfect for patios, balconies, or tight spaces.</p>\n<p class=\"font-claude-response-body break-words whitespace-normal\"><em><strong>Workshop</strong> available for more information and DIY for $120. Last Sunday every month in Fort Pierce.</em></p>", "qxfp57o8at43": "A working farm on your property, and someone who shows up every week to keep it alive.\n[gff_express_start]", "l35sfxdr1c28": "[gff_agreement]", "256k9yw0hrbi": "<p style=\"text-align: center;\">[gff_convince]</p>", "a3msy9vruid2": "[gff_account]", "xvhulbmg7cp5": "[aerial_timelapse]", "tz5ixh0u9f71": "[gff_garden_invite]"};
